import { test, expect } from '@playwright/test';
import { backend, login } from '../support/backend';
test("CRS-01-SC-001", async ({page})=>{
    const networkRequests:string[]=[];
    page.on('request',req=>{if(/course|curriculum/i.test(req.url()))networkRequests.push(req.url());});
    await backend(page,{academy:true}); await login(page);
    await expect(page.getByRole('button',{name:'Courses',exact:true})).toBeVisible();
    await expect(page.getByRole("tab", { name: "Today", exact: true })).toBeVisible();
    await page.getByRole("button", { name: "Courses", exact: true }).click();
    await expect(page.getByRole("heading", { name: "Courses", exact: true })).toBeVisible();
    await expect(page.getByText("No courses yet", { exact: true })).toBeVisible();
    await expect(page.getByRole("button", { name: "Create course", exact: true })).toBeVisible();
    await expect(page.getByRole("tab", { name: "Today", exact: true })).toBeVisible();
    await expect(page.getByRole("tab", { name: "Schedule", exact: true })).toBeVisible();
    await expect(page.getByRole("tab", { name: "Feedback", exact: true })).toBeVisible();
    await expect(page.getByRole("tab", { name: "Students", exact: true })).toBeVisible();
    await expect(page.getByRole("tab", { name: "Fees", exact: true })).toBeVisible();
    await expect(page.getByText("Course pilot — not synced", { exact: true })).toBeVisible();
});

